  'main.py':
    "import random\nimport pgzrun\n\nWIDTH = 800\nHEIGHT = 600\nTITLE = 'Escudos contra Invasores'\nTAMANHO = 6\nESCUDO_Y = 440\nESCUDO_X = [110, 290, 470, 650]\n\n# O desenho de um escudo: cada # é um pedacinho que um tiro pode arrancar.\nFORMA = [\n    '...########...',\n    '..##########..',\n    '.############.',\n    '##############',\n    '##############',\n    '##############',\n    '####......####',\n    '###........###',\n]\n\nescudos = []\ninvasores = []\nbombas = []\nexplosoes = []\ncanhao = Actor('canhao')\ntiro = Actor('tiro')\nmarcha = 1\nvidas = 3\npontos = 0\nvenceu = False\n\n\ndef montar_escudos():\n    escudos.clear()\n    for numero in range(len(ESCUDO_X)):\n        grade = []\n        for linha in FORMA:\n            pedacos = []\n            for letra in linha:\n                pedacos.append(letra == '#')\n            grade.append(pedacos)\n        escudos.append(grade)\n\n\ndef montar_invasores():\n    invasores.clear()\n    tipos = ['invasor_a', 'invasor_b', 'invasor_c']\n    for fila in range(3):\n        for coluna in range(8):\n            invasor = Actor(tipos[fila])\n            invasor.pos = (150 + coluna * 70, 90 + fila * 55)\n            invasores.append(invasor)\n\n\ndef novo_jogo():\n    global vidas, pontos, venceu, marcha\n    vidas = 3\n    pontos = 0\n    venceu = False\n    marcha = 1\n    bombas.clear()\n    explosoes.clear()\n    montar_escudos()\n    montar_invasores()\n    canhao.pos = (WIDTH / 2, 560)\n    tiro.y = -20\n\n\ndef estragar(numero, linha, coluna):\n    # A explosão arranca o pedaço atingido e alguns vizinhos, sorteados.\n    grade = escudos[numero]\n    for mais_linha in range(-1, 2):\n        for mais_coluna in range(-1, 2):\n            perto_linha = linha + mais_linha\n            perto_coluna = coluna + mais_coluna\n            if 0 <= perto_linha < len(grade) and 0 <= perto_coluna < len(grade[0]):\n                if mais_linha == 0 and mais_coluna == 0 or random.randint(1, 3) > 1:\n                    grade[perto_linha][perto_coluna] = False\n\n\ndef bateu_no_escudo(x, y):\n    for numero in range(len(escudos)):\n        coluna = int((x - ESCUDO_X[numero]) // TAMANHO)\n        linha = int((y - ESCUDO_Y) // TAMANHO)\n        if 0 <= linha < len(FORMA) and 0 <= coluna < len(FORMA[0]):\n            if escudos[numero][linha][coluna]:\n                estragar(numero, linha, coluna)\n                explodir(x, y)\n                return True\n    return False\n\n\ndef explodir(x, y):\n    explosao = Actor('explosao')\n    explosao.pos = (x, y)\n    explosoes.append(explosao)\n    clock.schedule(apagar_explosao, 0.15)\n\n\ndef apagar_explosao():\n    if explosoes:\n        explosoes.pop(0)\n\n\ndef soltar_bomba():\n    if invasores and not venceu and vidas > 0:\n        invasor = random.choice(invasores)\n        bomba = Actor('bomba')\n        bomba.midtop = invasor.midbottom\n        bombas.append(bomba)\n\n\ndef marchar():\n    global marcha\n    descer = False\n    for invasor in invasores:\n        invasor.x = invasor.x + marcha\n        if invasor.right > WIDTH - 10 or invasor.left < 10:\n            descer = True\n    if descer:\n        marcha = -marcha\n        for invasor in invasores:\n            invasor.y = invasor.y + 16\n\n\ndef draw():\n    screen.blit('fundo', (0, 0))\n    for numero in range(len(escudos)):\n        grade = escudos[numero]\n        for linha in range(len(grade)):\n            for coluna in range(len(grade[linha])):\n                if grade[linha][coluna]:\n                    x = ESCUDO_X[numero] + coluna * TAMANHO\n                    y = ESCUDO_Y + linha * TAMANHO\n                    screen.draw.filled_rect(Rect((x, y), (TAMANHO, TAMANHO)), (60, 220, 90))\n    for invasor in invasores:\n        invasor.draw()\n    for bomba in bombas:\n        bomba.draw()\n    for explosao in explosoes:\n        explosao.draw()\n    tiro.draw()\n    canhao.draw()\n    screen.draw.text('Pontos: ' + str(pontos), topleft=(12, 8), fontsize=30, color='white')\n    screen.draw.text('Vidas: ' + str(vidas), topright=(WIDTH - 12, 8), fontsize=30, color='white')\n    if venceu:\n        screen.draw.text('A Terra está salva!', center=(WIDTH / 2, 300), fontsize=56, color='yellow')\n    if vidas == 0:\n        screen.draw.text('Fim de jogo! Espaço recomeça', center=(WIDTH / 2, 300), fontsize=48, color='orange')\n\n\ndef update():\n    global vidas, pontos, venceu\n    if venceu or vidas == 0:\n        return\n    if keyboard.left and canhao.left > 0:\n        canhao.x = canhao.x - 5\n    if keyboard.right and canhao.right < WIDTH:\n        canhao.x = canhao.x + 5\n    marchar()\n    if tiro.y > -20:\n        tiro.y = tiro.y - 9\n        if bateu_no_escudo(tiro.x, tiro.top):\n            tiro.y = -20\n    for invasor in list(invasores):\n        if invasor.colliderect(tiro):\n            invasores.remove(invasor)\n            tiro.y = -20\n            pontos = pontos + 10\n            sounds.acerto.play()\n        elif invasor.bottom > ESCUDO_Y:\n            vidas = 0\n    for bomba in list(bombas):\n        bomba.y = bomba.y + 4\n        if bateu_no_escudo(bomba.x, bomba.bottom) or bomba.top > HEIGHT:\n            bombas.remove(bomba)\n        elif bomba.colliderect(canhao):\n            bombas.remove(bomba)\n            explodir(canhao.x, canhao.y)\n            vidas = vidas - 1\n            sounds.dano.play()\n    if not invasores:\n        venceu = True\n        sounds.vitoria.play()\n\n\ndef on_key_down(key):\n    if key != keys.SPACE:\n        return\n    if venceu or vidas == 0:\n        novo_jogo()\n    elif tiro.y <= -20:\n        # Um tiro de cada vez, como nos fliperamas antigos.\n        tiro.midbottom = canhao.midtop\n        sounds.tiro.play()\n\n\nnovo_jogo()\nclock.schedule_interval(soltar_bomba, 0.7)\npgzrun.go()\n",
  'README.md':
    '# Escudos contra Invasores\n\nDefenda a Terra atrás de escudos que se desfazem pedaço por pedaço a cada tiro.\n\nUm exemplo original feito com [Pygame Zero](https://pygame-zero.readthedocs.io/): o\nprograma inteiro está em `main.py` e é o mesmo nas versões de Blocos e de Código da\ngaleria.\n\n## Como jogar\n\nMova o canhão com as setas e atire com espaço (um tiro de cada vez). Os escudos protegem, mas se desfazem: dá até para abrir um buraco atirando por baixo.\n\n## Ideias para mudar\n\n- Mude o desenho dos escudos na lista FORMA.\n- Faça a explosão arrancar mais pedaços.\n- Acrescente uma quarta fila de invasores.\n\n## Imagens e sons\n\nO Pygame Zero procura as imagens em `images/`, os sons em `sounds/` e as músicas em\n`music/`, pelo nome do arquivo sem a extensão: `Actor(\'nave\')` usa `images/nave`.\nPara trocar um desenho, edite-o no Pinta pelo Estúdio, ou traga outro e use no código o\nnome que o painel mostra em "nome no código".\n\n## Jogar no computador\n\nO Pygame Zero roda no computador com o pygame-ce:\n\n```\npython -m pip install pygame-ce==2.5.8 numpy\npython -m pip install --no-deps pgzero==1.2.1\npython main.py\n```\n\nO programa termina com `pgzrun.go()`, então `python main.py` já abre o jogo. Num programa\nsem essa linha, use `python -X utf8 -m pgzero main.py` (o `-X utf8` mantém os acentos\ncertos no Windows).\n\nAo baixar o projeto pelo Estúdio, os desenhos em SVG ganham uma cópia em PNG, que é o\nformato que o Pygame Zero do computador abre.\n',
